display.text:
        requires self.wf(), !self.is_empty(),
        ensures
            ll.wf(),
            ll.page_id() == self.page_id(),
            ll.block_size() == self.block_size(),
            ll.instance() == self.instance,
            ll.heap_id().is_none(),
            ll.fixed_page(),
    {
        let tracked ll: LL;
        let p = core::ptr::null_mut::<Node>();
        let res = atomic_with_ghost!(
            &self.atomic => fetch_and(3);
            update old_v -> new_v;
            ghost g => {
                self.emp_inst.borrow().agree(self.emp.borrow(), &g.0);
                assert(self.emp@.value() == g.0.value());
                let tracked (mut y, g_opt) = g;
                assert(g_opt.is_some());
                let tracked (delay_token, ghost_ll) = g_opt.tracked_unwrap();
                assert(ghost_ll.wf());
                delay_value = delay_token.value().to_int();
                ll = ghost_ll;
                let mut data = ll.data@;
                data.len = 0;
                let tracked new_ll = LL {
                    first: p,
                    data: Ghost(data),
                    perms: Tracked(Map::tracked_empty()),
                };
                assert(new_ll.wf());
                assert(res == old_v);
                g = (y, Some((delay_token, new_ll)));
            }
        );
        let ret_ll = LL {
            first: res.with_addr(res.addr() & !3),
            data: Ghost(ll.data@),
            perms: Tracked(ll.perms.get()),
        };
        proof {
            assert(res.addr() & !3 == ll.ptr().addr()) by(bit_vector)
                requires res as int == ll.ptr() as int + delay_value,
                    ll.ptr() as int % 4 == 0,
                    delay_value <= 3,
                    delay_value >= 0;
            assert forall |i: nat| ret_ll.valid_node(i, #[trigger] ret_ll.next_ptr(i))
            by {
                assert(ll.valid_node(i, ll.next_ptr(i)));
            }
            assert(ret_ll.wf());
        }
        ret_ll
    }
}

